GRAM = [
("B1", "정중한 의문문 — 도치형 vs 구어형", "« Pouvez-vous vous présenter ? » (도치) ↔ « Vous pouvez vous présenter ? » (구어). 면접에서는 도치형 « Avez-vous des références ? », « Où vous voyez-vous dans deux ans ? » 가 자연스럽다. 3인칭 -t- 삽입(a-t-il)과 달리 vous 의문문은 간단해서 공손함을 만들기 쉽다."),
("B1", "의문사 qu'est-ce qui / qu'est-ce que", "« Qu'est-ce qui vous attire chez nous ? » (주어) / « Qu'avez-vous appris pendant ce stage ? » (목적어). 면접 질문은 모두 정중체이므로 도치형 목적어 의문사의 형태도 자연스럽게 익힌다."),
("B2", "조건법과 가정 — que feriez-vous / Je serais ravie", "« Je serais ravie. » « J'en parlerais quand même, mais calmement. » 조건법 현재는 완곡·가정을 동시에 나타낸다. 상황 질문(mise en situation)은 « Si ..., que faites-vous ? » (현재) 또는 « Que feriez-vous si ... ? » 로 묻는다."),
("B2", "pour que + 접속법 / quel que soit", "« Je garde la racine pour que l'oignon tienne. » « quelle que soit la réponse » 두 표현 모두 접속법을 요구한다. 면접 상황에서 목적·양보를 정확히 말하는 틀로 유용."),
("B1", "depuis + 현재 / il y a / dès", "« Une table attend depuis quarante minutes. » « Je me lève à cinq heures depuis l'âge de quatorze ans. » depuis 는 지속, « dès la semaine prochaine » 는 시작 시점, « il y a six mois » 는 과거의 한 점을 나타낸다."),
("B2", "간접 인용과 보고 — il m'a glissé que", "« Karim m'a glissé : « Celui-là, je le veux. » » 직접 인용을 « Il m'a dit qu'il le voulait. » 로 바꾸면 시제가 일치한다. 구어에서는 직접 인용이 더 생생하다."),
("B1", "관계절 qui / que / où — Un ancien patron qu'on peut appeler", "« Un ancien patron qu'on peut appeler », « un restaurant où je serai bien ». que 는 목적어, qui 는 주어. 이력서·추천 표현에서 반복해서 쓰인다."),
]

